{
  "version": 3,
  "description": "wtN/<repo> から base/<target_repo>/<target_path> への相対 symlink 設定。 target_repo は WT 間で共有したいファイルを置くメインリポ名に置換し、 不要な link は削除してください。",
  "links": [
    {
      "path": "CLAUDE.local.md",
      "target_repo": "demo",
      "target_path": "CLAUDE.local.md",
      "description": "ローカル向け CLAUDE 指示（Git 管理外）"
    },
    {
      "path": ".env",
      "target_repo": "demo",
      "target_path": ".env",
      "description": "環境変数（Git 管理外）"
    },
    {
      "path": ".claude/settings.local.json",
      "target_repo": "demo",
      "target_path": ".claude/settings.local.json",
      "description": "Claude Code のローカル設定"
    },
    {
      "path": ".pecot/config/hooks-config.json",
      "target_repo": "demo",
      "target_path": ".pecot/config/hooks-config.json",
      "description": "pecot hooks 有効/無効設定（main WT と共有）"
    },
    {
      "path": ".pecot/config/projects/.active",
      "target_repo": "demo",
      "target_path": ".pecot/config/projects/.active",
      "description": "active project ポインタ（main WT と共有）"
    },
    {
      "path": ".pecot/work",
      "target_repo": "demo",
      "target_path": ".pecot/work",
      "description": "作業ファイル置き場（main WT の .pecot/work を共有）"
    }
  ]
}
